/**
 * Coin Change (LeetCode #322)
 * Time: O(amount * coins) | Space: O(amount)
 *
 * Find minimum number of coins to make up the given amount.
 * Returns -1 if not possible.
 */

function coinChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;

  for (let i = 1; i <= amount; i++) {
    for (const coin of coins) {
      if (coin <= i && dp[i - coin] + 1 < dp[i]) {
        dp[i] = dp[i - coin] + 1;
      }
    }
  }

  return dp[amount] === Infinity ? -1 : dp[amount];
}

// Variant: Count number of ways to make change
function coinChangeWays(coins, amount) {
  const dp = new Array(amount + 1).fill(0);
  dp[0] = 1;
  for (const coin of coins) {
    for (let i = coin; i <= amount; i++) {
      dp[i] += dp[i - coin];
    }
  }
  return dp[amount];
}

// Examples
console.log(coinChange([1, 5, 10, 25], 36));    // 3 (25+10+1)
console.log(coinChange([2], 3));                // -1
console.log(coinChangeWays([1, 2, 5], 5));      // 4

module.exports = { coinChange, coinChangeWays };

/**
 * Union-Find (Disjoint Set Union)
 * find: O(α(n)) amortized | union: O(α(n)) amortized
 *
 * Efficiently tracks connected components.
 * Used for: Kruskal's MST, cycle detection, network connectivity.
 */

class UnionFind {
  constructor(n) {
    this.parent = Array.from({ length: n }, (_, i) => i);
    this.rank = new Array(n).fill(0);
    this.components = n;
  }

  find(x) {
    if (this.parent[x] !== x) {
      this.parent[x] = this.find(this.parent[x]); // Path compression
    }
    return this.parent[x];
  }

  union(x, y) {
    const px = this.find(x);
    const py = this.find(y);
    if (px === py) return false; // Already connected

    // Union by rank
    if (this.rank[px] < this.rank[py]) {
      this.parent[px] = py;
    } else if (this.rank[px] > this.rank[py]) {
      this.parent[py] = px;
    } else {
      this.parent[py] = px;
      this.rank[px]++;
    }
    this.components--;
    return true;
  }

  connected(x, y) {
    return this.find(x) === this.find(y);
  }
}

// Example: detect cycle in undirected graph
function hasCycle(n, edges) {
  const uf = new UnionFind(n);
  for (const [u, v] of edges) {
    if (!uf.union(u, v)) return true; // Already connected = cycle
  }
  return false;
}

const uf = new UnionFind(5);
uf.union(0, 1); uf.union(1, 2); uf.union(3, 4);
console.log(uf.connected(0, 2)); // true
console.log(uf.connected(0, 3)); // false
console.log(uf.components);      // 2

module.exports = { UnionFind };

"""
Spiral Matrix (LeetCode #54)
Time: O(m*n) | Space: O(1)

Traverse a 2D matrix in spiral order.
"""

def spiral_order(matrix):
    if not matrix: return []
    result = []
    top, bottom, left, right = 0, len(matrix)-1, 0, len(matrix[0])-1

    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

def generate_spiral(n):
    """Generate n x n spiral matrix."""
    matrix = [[0] * n for _ in range(n)]
    top, bottom, left, right = 0, n-1, 0, n-1
    num = 1
    while top <= bottom and left <= right:
        for col in range(left, right+1): matrix[top][col] = num; num += 1
        top += 1
        for row in range(top, bottom+1): matrix[row][right] = num; num += 1
        right -= 1
        if top <= bottom:
            for col in range(right, left-1, -1): matrix[bottom][col] = num; num += 1
            bottom -= 1
        if left <= right:
            for row in range(bottom, top-1, -1): matrix[row][left] = num; num += 1
            left += 1
    return matrix

if __name__ == '__main__':
    m = [[1,2,3],[4,5,6],[7,8,9]]
    print(spiral_order(m))  # [1,2,3,6,9,8,7,4,5]
    for row in generate_spiral(4): print(row)
